def solve(inputs: dict) -> float:
    x = inputs["x"]
    constant = inputs["constant"]
    modulus = inputs["modulus"]
    iterations = inputs["iterations"]

    for _ in range(iterations):
        x = (x * x + constant) % modulus

    return float(x)

